**Gates before launch.** I run four gates in order and stop at the first one that fails. First, I check that spe/predictions/r04.yaml and spe/plans/r04.md are in the commit from 10 minutes ago. In the same step I check two inputs. spe/evals/tasks/answers.json must have 50 entries, because the original set had 40 and the plan says 50. The runner must also accept `--config C2`. Second, I run the grader selftest. grade.py must score an oracle labels file built from answers.json at 1.0. It must fail an empty file, and it must score a file of wrong labels at 0. Third, I regrade round 3's saved labels with this round's grade.py as a control and compare the result to round 3's logged numbers. Any change counts as a grader change. I log it in spe/failures.md before launch. Fourth, I do a dry run with `args.only = ["B:T003", "C2:T017"]` and `args.trials = 1`. Every phase must return valid output, and the transcripts must land in the transcript directory. I then use the run's reported usage in place of the `EST` defaults. The unmeasured cost estimate is about $38 against the $40 cap. The script skips any trial that would cross the cap and logs it. If all four gates pass, I save the script as spe/evals/harness/r04-workflow.js, commit it locally as `spe(r04): add eval workflow script`, and launch. I chose two defaults the situation did not give. The first is the runner command: I assume r03 called the triage runner as `node spe/evals/harness/run-triage.js` with these flags and that it reports `cost_usd`. You can override it with `args.runner`. The second is the default for `args.agentLogDir`, which is the directory of Workflow subagent logs from this session.

```js
export const meta = {
  name: 'triage-spe-eval',
  description: 'SPE eval for the triage agent. Configs B and C2, 50 tickets, 5 trials per cell, code grader first, Opus tone judge, spend cap from args.',
  phases: [
    { title: 'Preflight' },
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Top-up' },
    { title: 'Judge' },
    { title: 'Synthesis' },
  ],
}

const A = args ?? {}
const ROUND = 4
const RR = 'r' + String(ROUND).padStart(2, '0')

const CONFIGS = A.configs ?? ['B', 'C2']
const TICKETS = A.tickets ?? []
const TRIALS = A.trials ?? 5
const EXPECTED_TICKETS = A.expectedTickets ?? 50
const ONLY = A.only ? new Set(A.only) : null
const RUNNER = A.runner ?? 'node spe/evals/harness/run-triage.js'
const TICKET_DIR = A.ticketDir ?? 'spe/evals/tasks/tickets'
const TRANSCRIPTS = A.transcriptDir ?? `spe/runs/${RR}/transcripts`
const RESULTS = `spe/evals/results/${RR}`
const AGENT_LOGS = A.agentLogDir ?? null
const CONCURRENCY = A.concurrency ?? 10
const TOPUP_PER_CELL = A.topUpPerCell ?? 5
const TOPUP_MAX_TRIALS = A.topUpMaxTrials ?? 60
const JUDGE_BATCH = A.judgeBatch ?? 20
const MAX_VOIDS = A.maxVoids ?? 5
const MODELS = { driver: A.driverModel ?? 'opus', helper: 'opus', judge: 'opus' }
// Unmeasured estimates. The dry run replaces them through args.est.
const EST = Object.assign(
  { trialUsd: 0.02, driverUsd: 0.12, gradeUsd: 0.25, scanUsd: 0.2, judgeBatchUsd: 0.45, synthUsd: 0.8 },
  A.est ?? {},
)
const CATEGORIES = ['billing', 'bug', 'how-to', 'account', 'outage']
const PRIORITIES = ['P1', 'P2', 'P3', 'P4']
const FORBIDDEN = ['spe/evals/graders', 'spe/evals/tasks/answers.json', 'spe/predictions']

const skips = []
const voids = []
const harnessErrors = []

const budget = {
  cap: A.spendCapUsd ?? 40,
  spent: 0,
  held: 0,
  tail: 0,
  free() { return this.cap - this.spent - this.held - this.tail },
  reserve(est) {
    if (est > this.free()) return false
    this.held += est
    return true
  },
  settle(est, actual) {
    this.held -= est
    this.spent += actual
  },
  take(est) {
    const fromTail = Math.min(this.tail, est)
    if (est - fromTail > this.free()) return false
    this.tail -= fromTail
    this.spent += est
    return true
  },
}

function halt(reason, extra) {
  log('HALT: ' + reason)
  return { round: ROUND, halted: reason, spend_usd: round3(budget.spent), skips, voids, harness_errors: harnessErrors, ...(extra ?? {}) }
}

function round3(x) { return x == null ? null : Math.round(x * 1000) / 1000 }

async function call(prompt, opts) {
  try {
    return await agent(prompt, opts)
  } catch (e) {
    log(`agent failed: ${opts.label}: ${e && e.message}`)
    return null
  }
}

function trialId(config, ticket, k) { return `${RR}-${config}-${ticket}-${k}` }

function passed(t) { return t.g && t.g.category_ok && t.g.priority_ok }

function groupBy(list, key) {
  const m = new Map()
  for (const x of list) {
    const k = key(x)
    if (!m.has(k)) m.set(k, [])
    m.get(k).push(x)
  }
  return m
}

function shuffle(arr, seed) {
  const a = arr.slice()
  let x = (seed >>> 0) || 1
  for (let i = a.length - 1; i > 0; i--) {
    x = (x * 1664525 + 1013904223) >>> 0
    const j = x % (i + 1)
    const tmp = a[i]
    a[i] = a[j]
    a[j] = tmp
  }
  return a
}

const TRIAL_SCHEMA = {
  type: 'object',
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          trial_index: { type: 'integer' },
          status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
          category: { type: 'string' },
          priority: { type: 'string' },
          reply: { type: 'string' },
          runtime_ms: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          tokens_in: { type: 'integer' },
          tokens_out: { type: 'integer' },
          cost_usd: { type: 'number' },
          error: { type: 'string' },
        },
        required: ['trial_index', 'status'],
      },
    },
  },
  required: ['trials'],
}

const SCAN_SCHEMA = {
  type: 'object',
  properties: {
    scan_ok: { type: 'boolean' },
    peeked: {
      type: 'array',
      items: {
        type: 'object',
        properties: { trial_id: { type: 'string' }, path: { type: 'string' }, source: { type: 'string' } },
        required: ['trial_id', 'path'],
      },
    },
    notes: { type: 'string' },
  },
  required: ['scan_ok', 'peeked'],
}

const GRADE_SCHEMA = {
  type: 'object',
  properties: {
    grader_ok: { type: 'boolean' },
    grader_error: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          expected_category: { type: 'string' },
          expected_priority: { type: 'string' },
        },
        required: ['trial_id', 'category_ok', 'priority_ok'],
      },
    },
  },
  required: ['grader_ok', 'rows'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    rows: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          tone_score: { type: 'integer', minimum: 1, maximum: 5 },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
        required: ['id', 'tone_score', 'tone_pass', 'reason'],
      },
    },
  },
  required: ['rows'],
}

const FAILURE_SCHEMA = {
  type: 'object',
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          existing_f: { type: 'string' },
          kind: { type: 'string' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          fix: { type: 'string' },
        },
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'configs', 'count', 'fix'],
      },
    },
  },
  required: ['types'],
}

const CRITIC_SCHEMA = {
  type: 'object',
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    metric_map: { type: 'array', items: { type: 'object', properties: { predicted: { type: 'string' }, measured: { type: 'string' } } } },
    notes: { type: 'string' },
  },
  required: ['complete', 'gaps'],
}

function driverPrompt(s) {
  const idx = []
  for (let k = s.start; k < s.start + s.n; k++) idx.push(k)
  return [
    `You run trials of the triage support agent. Run the command below once for each trial index in ${JSON.stringify(idx)}. Run them one at a time.`,
    '',
    `  ${RUNNER} --config ${s.config} --ticket ${s.ticket} --seed <index> --json --transcript ${TRANSCRIPTS}/${RR}-${s.config}-${s.ticket}-<index>.jsonl`,
    '',
    'Rules:',
    '- You may run only that command. Do not read, open, list, search, or print any file or directory.',
    `- Do not touch ${FORBIDDEN.join(', ')}. A trial that touches them is voided.`,
    '- If a run hits a rate limit, wait 30 seconds and retry it once. If it still fails, report status rate_limited.',
    '- If the runner crashes or prints no JSON, report status harness_error with the error text.',
    '- Copy label.category, label.priority, reply, and the usage numbers from the runner JSON exactly. Do not fix, judge, or rerun a result.',
    '- Report one row per trial index.',
  ].join('\n')
}

async function runTrials(specs, phaseTitle) {
  const done = []
  for (let i = 0; i < specs.length; i += CONCURRENCY) {
    const wave = []
    for (const s of specs.slice(i, i + CONCURRENCY)) {
      const est = s.n * EST.trialUsd + EST.driverUsd
      if (budget.reserve(est)) {
        wave.push({ s, est })
      } else {
        skips.push({ cell: s.cellId, trials: s.n, phase: phaseTitle, reason: 'spend cap', est_usd: round3(est) })
        log(`skip ${s.cellId} x${s.n}: it would cross the $${budget.cap} cap`)
      }
    }
    const res = await parallel(wave.map(w => () => call(driverPrompt(w.s), {
      label: `${phaseTitle.toLowerCase()} ${w.s.cellId}`,
      phase: phaseTitle,
      schema: TRIAL_SCHEMA,
      model: MODELS.driver,
    })))
    res.forEach((r, j) => {
      const { s, est } = wave[j]
      const rows = r && Array.isArray(r.trials) ? r.trials : []
      const runnerCost = rows.reduce((sum, t) => sum + (Number(t.cost_usd) || 0), 0)
      budget.settle(est, runnerCost + EST.driverUsd)
      if (!rows.length) {
        harnessErrors.push({ cell: s.cellId, phase: phaseTitle, error: 'driver returned no trials' })
        return
      }
      const seen = new Set()
      for (const t of rows) {
        if (t.trial_index < s.start || t.trial_index >= s.start + s.n || seen.has(t.trial_index)) continue
        seen.add(t.trial_index)
        const trial = { ...t, trial_id: trialId(s.config, s.ticket, t.trial_index), cellId: s.cellId, config: s.config, ticket: s.ticket, topUp: s.topUp }
        if (t.status === 'completed') done.push(trial)
        else harnessErrors.push({ trial_id: trial.trial_id, phase: phaseTitle, status: t.status, error: t.error ?? '' })
      }
      if (seen.size < s.n) harnessErrors.push({ cell: s.cellId, phase: phaseTitle, error: `driver reported ${seen.size} of ${s.n} trials` })
    })
    log(`${phaseTitle}: ${Math.min(i + CONCURRENCY, specs.length)}/${specs.length} cells, spend $${budget.spent.toFixed(2)} of $${budget.cap}`)
  }
  return done
}

async function scan(list, tag, phaseTitle) {
  if (!list.length) return { peeked: new Set() }
  if (!budget.take(EST.scanUsd)) return { halted: `spend cap reached before the ${tag} transcript scan` }
  const prompt = [
    'Check trial transcripts for reads of files that trials must not see. Use grep only. Do not open or summarize the matched files.',
    `Forbidden paths: ${FORBIDDEN.join(', ')}.`,
    `1. Grep the triage transcripts in ${TRANSCRIPTS} for those paths: grep -nE 'spe/evals/graders|spe/evals/tasks/answers\\.json|spe/predictions' ${TRANSCRIPTS}/*.jsonl`,
    AGENT_LOGS
      ? `2. Grep the trial driver logs in ${AGENT_LOGS} the same way. Count a match only when it is inside a tool call input (Read, Bash, Grep, Glob). The driver prompt names these paths in its rules, so prompt text does not count. A driver log is labeled like "trials B:T003" or "top-up B:T003". A real match there voids every trial of that cell from that phase.`
      : '2. No driver log directory was given. Say so in notes.',
    `3. Report each trial id that peeked, with the path and the source file of the match. Consider only these ids: ${JSON.stringify(list.map(t => t.trial_id))}`,
    'Set scan_ok to false if grep could not run or the transcript directory is missing.',
  ].join('\n')
  const r = await call(prompt, { label: `peek scan ${tag}`, phase: phaseTitle, schema: SCAN_SCHEMA, model: MODELS.helper })
  if (!r || !r.scan_ok) return { halted: `the ${tag} transcript scan did not run` }
  for (const p of r.peeked) voids.push({ ...p, tag })
  if (r.notes) log(`scan ${tag}: ${r.notes}`)
  return { peeked: new Set(r.peeked.map(p => p.trial_id)) }
}

async function grade(list, tag, phaseTitle) {
  if (!list.length) return { map: new Map() }
  if (!budget.take(EST.gradeUsd)) return { halted: `spend cap reached before the ${tag} grade` }
  const lines = list.map(t => JSON.stringify({ trial_id: t.trial_id, ticket: t.ticket, label: { category: t.category ?? '', priority: t.priority ?? '' } })).join('\n')
  const prompt = [
    'Run the code grader on these trial labels. Do not grade anything by eye.',
    `1. Write the JSON lines below to ${RESULTS}/${tag}-labels.jsonl, one object per line, exactly as given.`,
    `2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --labels ${RESULTS}/${tag}-labels.jsonl --out ${RESULTS}/${tag}-graded.jsonl`,
    '3. Return every row of the output file with category_ok, priority_ok, and the expected labels.',
    '4. If grade.py exits non-zero, or a trial_id is missing from its output, set grader_ok to false and put stderr in grader_error.',
    '',
    lines,
  ].join('\n')
  const r = await call(prompt, { label: `grade ${tag}`, phase: phaseTitle, schema: GRADE_SCHEMA, model: MODELS.helper })
  if (!r || !r.grader_ok) return { halted: `broken grader on ${tag}: ${r && r.grader_error ? r.grader_error : 'no result'}` }
  const map = new Map(r.rows.map(x => [x.trial_id, x]))
  const missing = list.filter(t => !map.has(t.trial_id))
  if (missing.length) return { halted: `grader skipped ${missing.length} trials on ${tag}` }
  return { map }
}

function metrics(list) {
  const n = list.length
  const mean = (xs, f) => xs.length ? xs.reduce((s, t) => s + f(t), 0) / xs.length : null
  const judged = list.filter(t => t.j)
  return {
    n,
    category_accuracy: round3(mean(list, t => t.g.category_ok ? 1 : 0)),
    priority_accuracy: round3(mean(list, t => t.g.priority_ok ? 1 : 0)),
    label_accuracy: round3(mean(list, t => passed(t) ? 1 : 0)),
    tone_judged: judged.length,
    tone_pass_rate: round3(mean(judged, t => t.j.tone_pass ? 1 : 0)),
    tone_mean: round3(mean(judged, t => t.j.tone_score)),
    tool_calls_mean: round3(mean(list, t => t.tool_calls ?? 0)),
    tool_errors_per_trial: round3(mean(list, t => t.tool_errors ?? 0)),
    runtime_ms_mean: round3(mean(list, t => t.runtime_ms ?? 0)),
    tokens_mean: round3(mean(list, t => (t.tokens_in ?? 0) + (t.tokens_out ?? 0))),
    cost_usd_per_trial: round3(mean(list, t => t.cost_usd ?? 0)),
  }
}

// Preflight
phase('Preflight')
if (!TICKETS.length) return halt('args.tickets is empty')
if (!ONLY && TICKETS.length !== EXPECTED_TICKETS) return halt(`expected ${EXPECTED_TICKETS} tickets, got ${TICKETS.length}`)
const badConfig = CONFIGS.filter(c => !['B', 'C2'].includes(c))
if (badConfig.length) log(`note: configs outside the approved plan: ${badConfig.join(', ')}`)

const allCells = []
for (const config of CONFIGS) for (const ticket of TICKETS) allCells.push({ cellId: `${config}:${ticket}`, config, ticket })
const cells = ONLY ? allCells.filter(c => ONLY.has(c.cellId)) : allCells
if (!cells.length) return halt('args.only matched no cells')

const nMain = cells.length * TRIALS
budget.tail = 2 * EST.scanUsd + 2 * EST.gradeUsd
  + Math.ceil((nMain + TOPUP_MAX_TRIALS) / JUDGE_BATCH) * EST.judgeBatchUsd
  + 2 * EST.synthUsd
const projected = nMain * EST.trialUsd + cells.length * EST.driverUsd + budget.tail
log(`round ${ROUND}: ${cells.length} cells x ${TRIALS} trials = ${nMain}. Projected spend $${projected.toFixed(2)} (unmeasured) against a $${budget.cap} cap.`)
if (budget.tail >= budget.cap) return halt('grading, judging, and synthesis alone would exceed the spend cap')

// Trials
phase('Trials')
const mainRaw = await runTrials(cells.map(c => ({ ...c, n: TRIALS, start: 1, topUp: false })), 'Trials')
const mainScan = await scan(mainRaw, 'main', 'Trials')
if (mainScan.halted) return halt(mainScan.halted)
if (mainScan.peeked.size > MAX_VOIDS) return halt(`possible leaked answer key: ${mainScan.peeked.size} trials peeked`)
const mainKept = mainRaw.filter(t => !mainScan.peeked.has(t.trial_id))

// Grade
phase('Grade')
const mainGrade = await grade(mainKept, 'main', 'Grade')
if (mainGrade.halted) return halt(mainGrade.halted)
for (const t of mainKept) t.g = mainGrade.map.get(t.trial_id)
const offEnum = mainKept.filter(t => !CATEGORIES.includes(t.category) || !PRIORITIES.includes(t.priority)).length
if (offEnum) log(`${offEnum} trials gave a label outside the allowed set. The grader scored them as wrong.`)

// Top-up
phase('Top-up')
const split = []
for (const [cellId, list] of groupBy(mainKept, t => t.cellId)) {
  const p = list.filter(passed).length
  if (p > 0 && p < list.length) split.push({ cellId, config: list[0].config, ticket: list[0].ticket })
}
let topUpLeft = TOPUP_MAX_TRIALS
const topSpecs = []
for (const c of split) {
  const n = Math.min(TOPUP_PER_CELL, topUpLeft)
  if (n <= 0) {
    skips.push({ cell: c.cellId, phase: 'Top-up', reason: `top-up cap of ${TOPUP_MAX_TRIALS} trials reached` })
    continue
  }
  topUpLeft -= n
  topSpecs.push({ ...c, n, start: TRIALS + 1, topUp: true })
}
log(`${split.length} split cells. ${topSpecs.length} get top-up trials.`)
const topRaw = await runTrials(topSpecs, 'Top-up')
const topScan = await scan(topRaw, 'topup', 'Top-up')
if (topScan.halted) return halt(topScan.halted)
if (mainScan.peeked.size + topScan.peeked.size > MAX_VOIDS) return halt('possible leaked answer key: too many trials peeked')
const topKept = topRaw.filter(t => !topScan.peeked.has(t.trial_id))
const topGrade = await grade(topKept, 'topup', 'Top-up')
if (topGrade.halted) return halt(topGrade.halted)
for (const t of topKept) t.g = topGrade.map.get(t.trial_id)

// Judge (tone only, blind to config)
phase('Judge')
const valid = mainKept.concat(topKept)
const blind = shuffle(valid, ROUND * 7919).map((t, i) => ({ id: 'j' + (i + 1), t }))
const byJid = new Map(blind.map(b => [b.id, b.t]))
const batches = []
for (let i = 0; i < blind.length; i += JUDGE_BATCH) {
  const batch = blind.slice(i, i + JUDGE_BATCH)
  if (budget.take(EST.judgeBatchUsd)) batches.push(batch)
  else {
    skips.push({ phase: 'Judge', reason: 'spend cap', replies: batch.length })
    log(`skip judge batch of ${batch.length}: it would cross the cap`)
  }
}
const judgeRes = await parallel(batches.map((batch, bi) => () => call([
  'You grade the tone of first replies to support tickets.',
  'Read the rubric at spe/evals/graders/judge.md and apply it exactly. You may read a ticket at ' + TICKET_DIR + '/<ticket>.md for context.',
  'Score tone only. Code already checked the category and priority, so ignore them.',
  'You do not know which configuration wrote each reply. Do not guess.',
  'Return one row per reply id. tone_score is 1 to 5 as the rubric defines it. tone_pass follows the rubric pass line.',
  '',
  JSON.stringify(batch.map(b => ({ id: b.id, ticket: b.t.ticket, reply: b.t.reply ?? '' }))),
].join('\n'), { label: `judge batch ${bi + 1}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: MODELS.judge })))
for (const r of judgeRes) {
  if (!r) continue
  for (const row of r.rows) {
    const t = byJid.get(row.id)
    if (t) t.j = row
  }
}
const unjudged = valid.filter(t => !t.j).length
if (unjudged) log(`${unjudged} replies have no tone score`)

// Aggregate
const results = {}
const cellsAllPass = {}
for (const config of CONFIGS) {
  const main = mainKept.filter(t => t.config === config)
  results[config] = { main: metrics(main), with_top_up: metrics(valid.filter(t => t.config === config)) }
  const byCell = groupBy(main, t => t.cellId)
  let full = 0
  for (const list of byCell.values()) if (list.length === TRIALS && list.every(passed)) full++
  cellsAllPass[config] = round3(byCell.size ? full / byCell.size : null)
}
const ceiling = ['category_accuracy', 'priority_accuracy', 'label_accuracy', 'tone_pass_rate']
  .filter(m => CONFIGS.every(c => results[c].main[m] === 1))
if (ceiling.length) log(`ceiling on ${ceiling.join(', ')}: every config scored 1. These predictions are not scorable. Check for a leak or a grader bug.`)

const summary = {
  round: ROUND,
  configs: CONFIGS,
  cells: cells.length,
  trials_per_cell: TRIALS,
  completed_main: mainKept.length,
  completed_top_up: topKept.length,
  results,
  cells_all_pass: cellsAllPass,
  ceiling,
  voids,
  skips,
  harness_errors: harnessErrors,
  spend_usd: round3(budget.spent),
  spend_note: 'Runner cost is measured. Driver, grader, judge, and synthesis cost are estimates from args.est.',
  judge_note: 'The judge is Opus, which is the same model family as the agent under test. No judge from another family was available.',
  metric_note: 'Headline metrics use the planned 5 trials per cell. with_top_up adds the extra trials from split cells.',
}

// Synthesis
phase('Synthesis')
const failing = valid.filter(t => !passed(t) || (t.j && !t.j.tone_pass) || (t.tool_errors ?? 0) > 0).map(t => ({
  trial_id: t.trial_id,
  config: t.config,
  ticket: t.ticket,
  got: { category: t.category, priority: t.priority },
  expected: { category: t.g.expected_category, priority: t.g.expected_priority },
  tone: t.j ? { score: t.j.tone_score, pass: t.j.tone_pass, reason: t.j.reason } : null,
  tool_errors: t.tool_errors ?? 0,
  transcript: `${TRANSCRIPTS}/${t.trial_id}.jsonl`,
}))
const synth = []
if (budget.take(EST.synthUsd)) {
  synth.push(() => call([
    'Analyze the failing trials of this eval. Group them into failure types.',
    'Read spe/failures.md and match each type to an existing F-number when it fits. Give a new name only for a new type.',
